-- Qiraat Phase 4 corroborated farsh additions. Approval is deliberately separate.
BEGIN;
SELECT set_config('app.device_id', 'auto-review', true);
CREATE TEMP TABLE _auto_new_ids(id text) ON COMMIT DROP;

SELECT 'v-L156-برحمه_ادخلوا-1-w2-a49-t7', 'Q04-R02', 'قرأ بضم التنوين وصلاً بخلف عنه.', false, 2, NULL, 'auto-review'
WHERE EXISTS (SELECT 1 FROM qiraat_entries e WHERE e.id = 'v-L156-برحمه_ادخلوا-1-w2-a49-t7' AND e.deleted_at IS NULL)
AND NOT EXISTS (SELECT 1 FROM qiraat_entry_authorities ea WHERE ea.entry_id = 'v-L156-برحمه_ادخلوا-1-w2-a49-t7' AND ea.authority_id = 'Q04-R02' AND ea.deleted_at IS NULL);
SELECT 'v-L233-لا_تكلم-1-w2-a105-t3', 'Q02-R02', 'قرأ بإثبات الياء الزائدة في الحالين.', true, 1, NULL, 'auto-review'
WHERE EXISTS (SELECT 1 FROM qiraat_entries e WHERE e.id = 'v-L233-لا_تكلم-1-w2-a105-t3' AND e.deleted_at IS NULL)
AND NOT EXISTS (SELECT 1 FROM qiraat_entry_authorities ea WHERE ea.entry_id = 'v-L233-لا_تكلم-1-w2-a105-t3' AND ea.authority_id = 'Q02-R02' AND ea.deleted_at IS NULL);
SELECT 'v-L429-s34a9b1-w2-a9-t20', 'Q07-R02', 'قرؤوا بإسكان السين.', true, 1, NULL, 'auto-review'
WHERE EXISTS (SELECT 1 FROM qiraat_entries e WHERE e.id = 'v-L429-s34a9b1-w2-a9-t20' AND e.deleted_at IS NULL)
AND NOT EXISTS (SELECT 1 FROM qiraat_entry_authorities ea WHERE ea.entry_id = 'v-L429-s34a9b1-w2-a9-t20' AND ea.authority_id = 'Q07-R02' AND ea.deleted_at IS NULL);


-- Entries made by the editor RPC come out 'reviewed'/'VERIFIED'; these must wait for a person.
UPDATE qiraat_entries SET review_status='unreviewed', verification_status='REVIEWED', review_source=NULL,
       review_note='أُضيف آليًا من كتاب القراءة وnquran.com — بانتظار المراجعة'
 WHERE id IN (SELECT id FROM _auto_new_ids) AND created_at >= now();
SELECT count(*) AS new_entries_waiting_for_review FROM qiraat_entries WHERE review_note LIKE 'أُضيف آليًا%';
COMMIT;
